def sort_array(arr: list) -> list:
    """Counting sort with dynamic range detection."""
    n = len(arr)
    if n <= 1:
        return list(arr)
    lo = hi = arr[0]
    for x in arr:
        if x < lo:
            lo = x
        elif x > hi:
            hi = x
    span = hi - lo + 1
    counts = [0] * span
    for x in arr:
        counts[x - lo] += 1
    result = []
    append = result.append
    for i in range(span):
        c = counts[i]
        if c == 1:
            append(i + lo)
        elif c > 1:
            result.extend([i + lo] * c)
    return result

