def sort_array(arr: list) -> list:
    """Optimized counting sort: pre-allocated result list, minimal overhead."""
    n = len(arr)
    if n == 0:
        return []
    offset = 10000
    counts = [0] * 20001
    for x in arr:
        counts[x + offset] += 1
    result = [0] * n
    idx = 0
    for i in range(20001):
        c = counts[i]
        if c:
            val = i - offset
            for _ in range(c):
                result[idx] = val
                idx += 1
